# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BASİT HARMONİK HAREKETTE KUVVET, İVME VE HIZIN KONUMA GÖRE DEĞİŞİMİ</text>\n  <line x1="60" y1="82" x2="640" y2="82" stroke="#334155" stroke-width="3"/>\n  <circle cx="100" cy="82" r="8" fill="#dc2626"/>\n  <text x="100" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">K (−r)</text>\n  <circle cx="350" cy="82" r="8" fill="#16a34a"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">O (x = 0 Denge)</text>\n  <circle cx="600" cy="82" r="8" fill="#dc2626"/>\n  <text x="600" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">L (+r)</text>\n  <circle cx="475" cy="82" r="6" fill="#2563eb"/>\n  <text x="475" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Uzanım (x)</text>\n  <path d="M 475 96 L 415 96" stroke="#dc2626" stroke-width="2.5"/>\n  <text x="445" y="112" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">F ve a daima O\'ya doğru!</text>\n  <rect x="25" y="125" width="205" height="118" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="127" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Sol Genlik Noktası (K: −r)</text>\n  <text x="38" y="168" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Hız:</tspan> v = 0 (Anlık durur)</text>\n  <text x="38" y="188" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">İvme:</tspan> a_max = ω²·r (+x yönlü)</text>\n  <text x="38" y="208" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Kuvvet:</tspan> F_max = m·ω²·r (+x)</text>\n  <text x="38" y="228" font-size="10.5" font-weight="bold" fill="#b91c1c">Uzanım maksimum: |x| = r</text>\n  <rect x="247" y="125" width="205" height="118" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Denge Konumu (O: x = 0)</text>\n  <text x="260" y="168" font-size="11" fill="#14532d">• <tspan font-weight="bold">Hız:</tspan> v_max = ω·r (Maksimum)</text>\n  <text x="260" y="188" font-size="11" fill="#14532d">• <tspan font-weight="bold">İvme:</tspan> a = 0 (Minimum)</text>\n  <text x="260" y="208" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kuvvet:</tspan> F = 0 (Net kuvvet 0)</text>\n  <text x="260" y="228" font-size="10.5" font-weight="bold" fill="#15803d">Herhangi x\'te: v = ω·kök(r² − x²)</text>\n  <rect x="470" y="125" width="205" height="118" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="572" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Sağ Genlik Noktası (L: +r)</text>\n  <text x="483" y="168" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Hız:</tspan> v = 0 (Anlık durur)</text>\n  <text x="483" y="188" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">İvme:</tspan> a_max = ω²·r (−x yönlü)</text>\n  <text x="483" y="208" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Kuvvet:</tspan> F_max = m·ω²·r (−x)</text>\n  <text x="483" y="228" font-size="10.5" font-weight="bold" fill="#b91c1c">Genel bağıntı: a = −ω²·x</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KUVVET-UZANIM, İVME-UZANIM VE HIZ-UZANIM GRAFİKLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Kuvvet – Uzanım ve İvme – Uzanım Grafiği</text>\n  <line x1="60" y1="145" x2="300" y2="145" stroke="#475569" stroke-width="1.5"/>\n  <line x1="180" y1="80" x2="180" y2="210" stroke="#475569" stroke-width="1.5"/>\n  <line x1="90" y1="90" x2="270" y2="200" stroke="#dc2626" stroke-width="3"/>\n  <text x="188" y="88" font-size="10.5" font-weight="bold" fill="#1e3a8a">+F_max (+a_max)</text>\n  <text x="188" y="210" font-size="10.5" font-weight="bold" fill="#1e3a8a">−F_max (−a_max)</text>\n  <text x="75" y="160" font-size="10.5" font-weight="bold" fill="#dc2626">−r</text>\n  <text x="270" y="140" font-size="10.5" font-weight="bold" fill="#dc2626">+r</text>\n  <text x="180" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">F = −m·ω²·x = −k·x  ve  a = −ω²·x (Doğrusal, Ters İşaretli)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Hız – Uzanım Grafiği ve Vektör Yönleri</text>\n  <line x1="400" y1="145" x2="640" y2="145" stroke="#475569" stroke-width="1.5"/>\n  <line x1="520" y1="80" x2="520" y2="210" stroke="#475569" stroke-width="1.5"/>\n  <ellipse cx="520" cy="145" rx="90" ry="50" fill="none" stroke="#16a34a" stroke-width="3"/>\n  <text x="528" y="90" font-size="10.5" font-weight="bold" fill="#166534">+v_max (ω·r)</text>\n  <text x="528" y="208" font-size="10.5" font-weight="bold" fill="#166534">−v_max</text>\n  <text x="412" y="160" font-size="10.5" font-weight="bold" fill="#92400e">−r</text>\n  <text x="615" y="160" font-size="10.5" font-weight="bold" fill="#92400e">+r</text>\n  <text x="520" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">v = ω·kök(r² − x²) · Uzanım vektörü x daima O\'dan dışarı!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BASİT HARMONİK HAREKETTE ENERJİ KORUNUMU VE DÖNÜŞÜMÜ</text>\n  <rect x="20" y="45" width="325" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Enerji – Uzanım Parabolleri</text>\n  <line x1="55" y1="190" x2="310" y2="190" stroke="#334155" stroke-width="1.5"/>\n  <line x1="182" y1="80" x2="182" y2="205" stroke="#334155" stroke-width="1.5"/>\n  <line x1="75" y1="95" x2="290" y2="95" stroke="#9333ea" stroke-width="2.5" stroke-dasharray="5,3"/>\n  <path d="M 75 190 Q 182 0 290 190" fill="none" stroke="#2563eb" stroke-width="2.5"/>\n  <path d="M 75 95 Q 182 285 290 95" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <text x="255" y="89" font-size="10" font-weight="bold" fill="#7e22ce">E_top (Sabit)</text>\n  <text x="182" y="120" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">E_K (Kinetik)</text>\n  <text x="105" y="135" font-size="10" font-weight="bold" fill="#dc2626">E_P (Potansiyel)</text>\n  <text x="75" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">−r</text>\n  <text x="182" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">O (0)</text>\n  <text x="290" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">+r</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Matematiksel Enerji Bağıntıları</text>\n  <rect x="375" y="82" width="290" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="520" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Toplam Mekanik Enerji (E_top):</text>\n  <text x="520" y="117" text-anchor="middle" font-size="10.5" fill="#581c87">E_top = (1/2)·k·r² = (1/2)·m·ω²·r² (Sürtünmesizde Sabit)</text>\n  <rect x="375" y="134" width="290" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="520" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Esneklik Potansiyel Enerjisi (E_P):</text>\n  <text x="520" y="169" text-anchor="middle" font-size="10.5" fill="#7f1d1d">E_P = (1/2)·k·x²  (Uçlarda maksimum, O\'da sıfır)</text>\n  <rect x="375" y="186" width="290" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="520" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Kinetik Enerji (E_K = E_top − E_P):</text>\n  <text x="520" y="221" text-anchor="middle" font-size="10.5" fill="#1e3a8a">E_K = (1/2)·m·v² = (1/2)·k·(r² − x²)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
